module wireless_coverage(input [5:0] router_mask, input [5:0] router_costs, input [7:0] K, output reg [15:0] min_cost); wire [15:0] cost [0:63]; generate for (param integer i=0; i<64; i++) begin: gen_config localparam [5:0] config = i; wire [5:0] mask = config & router_costs; wire [2:0] sum_r = mask[0] + mask[1] + mask[2] + mask[3] + mask[4] + mask[5]; wire cond_h0 = !(config[0] ^ config[1]); wire cond_h1 = !(config[1] ^ config[2]); wire cond_h2 = !(config[3] ^ config[4]); wire cond_h3 = !(config[4] ^ config[5]); wire cond_v0 = !(config[0] ^ config[3]); wire cond_v1 = !(config[1] ^ config[4]); wire cond_v2 = !(config[2] ^ config[5]); wire [2:0] bad = cond_h0 + cond_h1 + cond_h2 + cond_h3 + cond_v0 + cond_v1 + cond_v2; wire [15:0] temp = (bad[2] ? (K << 2) : 0) + (bad[1] ? (K <<1) :0) + (bad[0] ? K :0); cost[i] = {{temp}, 16'd0} + sum_r; end endgenerate wire [15:0] min_val = cost[0]; min_val = (cost[1] < min_val) ? cost[1] : min_val; min_val = (cost[2] < min_val) ? cost[2] : min_val; min_val = (cost[3] < min_val) ? cost[3] : min_val; min_val = (cost[4] < min_val) ? cost[4] : min_val; min_val = (cost[5] < min_val) ? cost[5] : min_val; assign min_cost = min_val; endmodule